import {challenge as C} from './shared.js';
export default [
C(9,2,'实现一次 Delta 记忆写入',{
 goal:'根据当前键的读取误差修正一个小型矩阵记忆。',signature:'delta_write(memory, key, value, beta)',contract:'memory 为 m×n，key 长 n，value 长 m，beta 为标量。约定预测 memory*key，更新 memory+beta*(value-prediction)*key^T，返回新矩阵。此为未加门控的教学 Delta 规则，不是完整 KDA。',context:'只把新内容不断加进记忆可能累积重复信息。Delta 写入先估计当前键对应的值，再根据误差修正。这个小公式帮助理解“修正”的含义；KDA 的门控、归一化和高效内核还需要阅读原论文与实现。',steps:['用更新前的 memory 计算每个输出维度的 prediction。','计算 error=value-prediction。','外积 error 与 key，乘 beta，加回旧 memory。'],worked:['memory=[[0,0]], key=[1,0], value=[2]。','预测为 0，误差为 2，beta=0.5。','更新后 [[1,0]]，只沿键指向的方向写入。'],mistake:'如果读取已经等于目标，仍重复加入完整 value，就不是误差修正规则。',transfer:'本题没有 KDA 的门控，不能用它的输出或复杂度代表 Kimi Linear；它只提供阅读矩阵状态的起点。',cases:[['delta_write([[0,0]],[1,0],[2],0.5)','[[1,0]]','首次写入'],['delta_write([[2,0]],[1,0],[2],1)','[[2,0]]','无误差不改'],['delta_write([[0,0],[0,0]],[0,1],[3,4],1)','[[0,3],[0,4]]','矩阵外积']],solution:'def delta_write(memory,key,value,beta):\n    pred=[sum(x*k for x,k in zip(row,key)) for row in memory]\n    return [[x+beta*(v-p)*k for x,k in zip(row,key)] for row,v,p in zip(memory,value,pred)]\n',quiz:['当前读取已等于 value，Delta 修正项是多少？',['value','0','key'],1,'误差为零，所以本题修正项为零。']
}),
C(9,4,'给流式状态标记 reset 与 detach',{
 goal:'实现明确区分状态数值和梯度历史计数的流式扫描。',signature:'state_trace(values, resets, detaches, decay)',contract:'三个列表等长，0≤decay≤1。初始 state=0、age=0；每步先 reset（数值与 age 清零），再 detach（只清 age），再 state=decay*state+value，age+=1。返回 (state,age) 列表。age 只是教学计数。',context:'状态能携带旧信息，并不意味着梯度还能回到所有旧操作。detach 断开求导历史，reset 改变前向数值。普通 Python 没有自动求导图，因此我们显式记录 age 来理解边界，但不把这个计数当作真实梯度。',steps:['维护 state 和 age 两个独立变量。','严格按 reset、detach、更新、记录的顺序执行。','相同边界上两者都发生时，reset 的清空效果仍保留。'],worked:['输入 [2,0]，decay=0.5。','第二步只 detach，状态从 2 变成 1，age 重置后变成 1。','若第二步 reset，则状态为 0；这两种结果不能混为一谈。'],mistake:'把每个文件块边界都当作 episode 结束，会无意缩短模型可用历史。',transfer:'真实项目应检查 state.detach()、reset mask 和优化器更新的不同位置。',cases:[['state_trace([2,0],[False,False],[False,True],0.5)','[(2,1),(1,1)]','截断保留数值'],['state_trace([2,0],[False,True],[False,False],0.5)','[(2,1),(0,1)]','重置清空数值'],['state_trace([1,1,1],[False]*3,[False]*3,1)','[(1,1),(2,2),(3,3)]','连续历史']],solution:'def state_trace(values,resets,detaches,decay):\n    state=0.0; age=0; out=[]\n    for v,r,d in zip(values,resets,detaches):\n        if r: state=0.0; age=0\n        if d: age=0\n        state=decay*state+v; age+=1\n        out.append((state,age))\n    return out\n',quiz:['detach 后前向状态一定归零吗？',['是','不是，数值保留','只在奇数步归零'],1,'detach 切断旧求导连接，不等于 reset。']
}),
C(9,6,'还原真正生效的训练配置',{
 goal:'按默认值、配置文件、命令行覆盖的顺序合并配置。',signature:'effective_config(defaults, file_config, cli)',contract:'三个普通字典使用扁平键，优先级 cli>file_config>defaults。None 在 cli 中表示未提供该覆盖；其他值包括 False、0 都是有效覆盖。返回新字典，不修改输入。',context:'源码支持 KDA，不等于一次训练实际启用 KDA。配置合并是把静态代码与运行意图连接起来的第一步。特别要分清“没有传参数”与“明确传了 False 或 0”，否则会把用户想禁用的功能重新开启。',steps:['复制 defaults，再应用 file_config。','遍历 cli，仅跳过值为 None 的项。','不能用 if value 判断是否覆盖，因为 False 与 0 也可能是明确选择。'],worked:['defaults={layers:4,kda:True}，文件把 layers 改成 8。','命令行 layers=None、kda=False。','有效配置为 layers=8、kda=False；还需日志确认实际构造路径。'],mistake:'过滤所有假值会丢失显式禁用设置。',transfer:'真实项目可能有嵌套字典和配置框架，这里的浅合并不替代框架语义；应查实际解析与覆盖顺序。',cases:[['effective_config({"layers":4,"kda":True},{"layers":8},{"layers":None,"kda":False})','{"layers":8,"kda":False}','优先级与显式禁用'],['effective_config({"lr":1},{},{"lr":0})','{"lr":0}','零是有效值'],['effective_config({}, {"seed":42},{})','{"seed":42}','新字段']],solution:'def effective_config(defaults,file_config,cli):\n    out=dict(defaults); out.update(file_config)\n    out.update({k:v for k,v in cli.items() if v is not None})\n    return out\n',quiz:['命令行 kda=False 应该被当作什么？',['没有提供','明确关闭','自动使用默认 True'],1,'只有题目约定的 None 表示没有提供覆盖。']
}),
C(9,7,'周项目：按 episode 管理流式记忆',{
 goal:'让状态跨连续数据块保留，在新 episode 时重置，并按固定窗口截断历史计数。',signature:'stream_memory(records, decay, window)',contract:'records 是按时间排列的 (episode,value) 对，window≥1。episode 与上一项不同则 state、age 清零；否则 age 达到 window 时只清 age。随后执行 state=decay*state+value、age+=1。返回 (state,age) 列表。',context:'数据加载器的每次 yield 不一定是新轨迹。综合项目把 episode 语义、状态递推与梯度窗口放在同一条时间线上。它仍是教学状态机，真实 TBPTT 要另用 autograd 验证梯度是否跨边界。',steps:['保存上一条 episode；首次或 episode 改变时重置两项状态。','同一 episode 内到窗口边界只清历史 age，不清数值。','更新并输出，检查切分窗口是否改变前向数值。'],worked:['records=[(a,2),(a,0),(a,0)]，decay=0.5、window=1。','每步历史都重新计数，但状态依次为 2、1、0.5。','换到 episode b 后旧状态不应污染 b 的第一步。'],mistake:'在 detach 边界也清空 state，会让结果随 window 改变。',transfer:'这是审查 OmniFM 状态边界的可运行模板：把示例中的判断替换为项目实际字段，再核对日志，而不是猜生产配置。',cases:[['stream_memory([("a",2),("a",0),("a",0)],0.5,1)','[(2,1),(1,1),(0.5,1)]','窗口不清数值'],['stream_memory([("a",2),("b",3)],0.5,8)','[(2,1),(3,1)]','新轨迹重置'],['stream_memory([("a",1),("a",1),("a",1)],1,2)','[(1,1),(2,2),(3,1)]','跨两步窗口']],extraTests:[{name:'改变窗口不改变前向数值',code:'r=[("a",1),("a",2),("a",3)]\na=stream_memory(r,0.7,1); b=stream_memory(r,0.7,9)\nassert [s for s,_ in a]==[s for s,_ in b]'}],solution:'def stream_memory(records,decay,window):\n    state=0.0; age=0; previous=object(); out=[]\n    for episode,v in records:\n        if episode!=previous: state=0.0; age=0\n        elif age>=window: age=0\n        state=decay*state+v; age+=1\n        out.append((state,age)); previous=episode\n    return out\n',quiz:['只缩短梯度历史窗口，在本题里应改变什么？',['状态数值','历史计数','episode 身份'],1,'前向递推保持一致，改变的是被记录的可追溯历史长度。']
})];
